"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["50924"],{62101(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_taxa_inscricao.valor_obrigatorio_quando_cobra","status":422,"titulo":"Processo que cobra taxa exige valor positivo"},"descricao":{"codigo":"uniplus.selecao.configuracao_taxa_inscricao.valor_obrigatorio_quando_cobra","requisitos":["UNI-REQ-0099"],"oQueAconteceu":["A defini\xe7\xe3o declarou `cobra` como verdadeiro, mas n\xe3o trouxe `valor`, ou trouxe um valor igual a\\nzero ou negativo. O processo que cobra taxa de inscri\xe7\xe3o precisa informar um valor positivo.","A recusa acontece depois de o sistema encontrar o processo e aceitar a precondi\xe7\xe3o de edi\xe7\xe3o. Um\\nvalor com mais de duas casas decimais \xe9 recusado antes, pela confer\xeancia de forma do pedido, e n\xe3o\\nchega a esta regra. As viola\xe7\xf5es do mesmo pedido saem juntas no array `errors[]`: esta causa pode\\naparecer ao lado de\\n[`fundamento_obrigatorio_quando_cobra`](/erros/uniplus.selecao.configuracao_taxa_inscricao.fundamento_obrigatorio_quando_cobra)\\nou de\\n[`fundamento_desconhecido`](/erros/uniplus.selecao.configuracao_taxa_inscricao.fundamento_desconhecido),\\nque valem para quem cobra.","Esta mesma confer\xeancia \xe9 refeita quando o sistema rel\xea a configura\xe7\xe3o congelada da vers\xe3o\\npublicada: em toda opera\xe7\xe3o que l\xea essa configura\xe7\xe3o e devolve a viola\xe7\xe3o ao chamador (a retifica\xe7\xe3o, a consulta dos formul\xe1rios,\\nas opera\xe7\xf5es da inscri\xe7\xe3o, entre outras; a lista completa est\xe1 no cabe\xe7alho da p\xe1gina).\\nPelo caminho normal de grava\xe7\xe3o, a configura\xe7\xe3o congelada nunca traz taxa cobrada sem valor\\npositivo, porque a defini\xe7\xe3o a recusa antes. Nessas leituras a recusa sai como viola\xe7\xe3o \xfanica,\\nsem a lista `errors[]`, e se refere \xe0 vers\xe3o congelada, n\xe3o ao pedido enviado."],"comoResolver":["Escolha entre:","- informar `valor` positivo, com no m\xe1ximo duas casas decimais, se o processo cobra taxa; ou\\n- declarar `cobra` como falso, sem valor e sem fundamentos de isen\xe7\xe3o, se o processo n\xe3o cobra.","Se a resposta trouxer mais de uma viola\xe7\xe3o em `errors[]`, corrija todas antes de reenviar.","Se a recusa apareceu em uma opera\xe7\xe3o que l\xea a configura\xe7\xe3o congelada (qualquer uma das listadas no cabe\xe7alho, exceto a defini\xe7\xe3o da pr\xf3pria configura\xe7\xe3o e a simula\xe7\xe3o), o pedido enviado agora n\xe3o \xe9 a causa: o sistema\\nrecusou a configura\xe7\xe3o congelada da vers\xe3o publicada, e redefinir a taxa do processo n\xe3o a\\ncorrige. A causa \xe9 investigada pela equipe t\xe9cnica do Uni+."],"ondeAparece":["Defini\xe7\xe3o da taxa de inscri\xe7\xe3o do processo seletivo","Retifica\xe7\xe3o em ato \xfanico","Consulta do formul\xe1rio renderiz\xe1vel do processo","Consulta do formul\xe1rio da inscri\xe7\xe3o","In\xedcio, salvamento, submiss\xe3o, cancelamento e descarte do rascunho da inscri\xe7\xe3o","Avalia\xe7\xe3o da inscri\xe7\xe3o","In\xedcio, confirma\xe7\xe3o e remo\xe7\xe3o de envio de documento da inscri\xe7\xe3o","Consulta e emiss\xe3o do comprovante da inscri\xe7\xe3o","Consulta administrativa da inscri\xe7\xe3o e dos documentos dela","Publica\xe7\xe3o de produto do edital e listagem de produtos previstos do processo","Notas do ENEM (importa\xe7\xe3o de lote, gera\xe7\xe3o do envio ao INEP e consulta de lotes e de envios)"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao taxa inscricao"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);